function create_quotation(frm) {
    if(frm.doc.docstatus == 2 || frm.doc.status == 'Completed' || frm.doc.status == 'Closed') {
        frappe.throw('OPR cannot be generated for Closed, Completed or Cancelled Sales Orders.');
        return;
    }
    // You can fetch data from the Issue and use it in the Quotation
    var customer = frm.doc.customer;
    var issue_details = frm.doc.description;

    // Create a new Quotation document
    frappe.model.open_mapped_doc({
       // method: "qcs_cvs.controller.so.make_opr",
       method: "btb_cvs_support.api.opr.get_mapped_opr",
        frm: frm
    });
}

function sum_field(rows, fieldname) {
    return (rows || []).reduce((acc, d) => acc + flt(d[fieldname]), 0);
}

