function set_total_nos_produced(frm) {
    const total = sum_field(frm.doc.production_schedule, "nos");
    if (Math.abs((frm.doc.total_nos_produced || 0) - total) > 0.01) {
        frm.set_value("total_nos_produced", total);
    }
}

function calculate_remaining_and_net(frm) {
    const remaining_value = (frm.doc.approx_value_ || 0) 
                          + (frm.doc.adjustment || 0) 
                          - (frm.doc.invoiced_value || 0);
    frm.set_value("remaining_value", remaining_value);

    const net_value = (frm.doc.invoiced_value || 0) 
                    + (frm.doc.consumption_value || 0);
    frm.set_value("net_value", net_value);

    if ((frm.doc.invoiced_value || 0) > 0) {
        const material_percent = - ((frm.doc.consumption_value || 0) / frm.doc.invoiced_value) * 100;
        frm.set_value("material_percent", material_percent);
    }
}

frappe.ui.form.on("Order Processing Request", {
    before_save(frm) {
        set_total_straight_sqm(frm);
        set_total_straight_nos(frm);
        set_total_fittings_sqm(frm);
        set_total_fittings_nos(frm);
        set_total_sqm_produced(frm);
        set_total_nos_produced(frm);

        const total_sqm = (frm.doc.total_straight_sqm || 0) + (frm.doc.total_fittings_sqm || 0);
        const total_no  = (frm.doc.total_straight_nos || 0) + (frm.doc.total_fittings_nos || 0);

        frm.set_value("total_sqm", total_sqm);
        frm.set_value("total_no", total_no);

        frm.set_value("remaining_sqm_production", total_sqm - (frm.doc.total_sqm_produced || 0));
        frm.set_value("remaining_nos_production", total_no - (frm.doc.total_nos_produced || 0));
        frm.set_value("remaining_sqm_delivery", total_sqm - (frm.doc.total_sqm_delivered || 0));
        frm.set_value("remaining_nos_delivery", total_no - (frm.doc.total_nos_delivered || 0));
        frm.set_value("remaining_produced_sqm_to_delivered", (frm.doc.total_sqm_produced || 0) - (frm.doc.total_sqm_delivered || 0));
        frm.set_value("remaining_produced_no_to_delivered", (frm.doc.total_nos_produced || 0) - (frm.doc.total_nos_delivered || 0));

        calculate_remaining_and_net(frm);
    },
    adjustment(frm) { calculate_remaining_and_net(frm); },
    approx_value_(frm) { calculate_remaining_and_net(frm); },
    consumption_value(frm) { calculate_remaining_and_net(frm); }
});

