                            if (so.docstatus === 2 || so.status === "Completed" || so.status === "Closed") {
                                frappe.throw(__("OPR cannot be generated for Closed, Completed or Cancelled Sales Orders"));
                                reject(); // stop save
                            } else {
                                resolve();
                            }
                        } else {
                            resolve();
                        }
                    }
                });
            });
        }
    }
});

