frappe.ui.form.on('Quotation', {
    validate: function(frm) {
        console.log('frm.doc : ',frm.doc);
      if (frm.doc.custom_cart_discount<0 || frm.doc.custom_cart_discount>40) {
            frappe.msgprint(__('Can Apply cart discount between 0 to 40'));
            frappe.validated = false;
            return
        }
    },
    after_save(frm, cdt, cdn) {
        if(frm.doc.custom_customizable == 1 && frm.doc.custom_cpq_amended==0 && 
        (frm.doc.amended_from != null || frm.doc.custom_created_from != null)){
            amendCPQ(frm,cdn);
        }
    },
	refresh(frm, cdt, cdn) {
	    hideSections(frm);
	    if(frm.doc.custom_customizable == 1) {
    	    if(frm.doc.items.length >0) createButtons(frm);
    	    assignQuoteLineItem(frm, cdn);
	        assignOneCPQQuoteTotal(frm,cdn)
	        if(frm.read_only !=1) loadOneCPQTab(frm);
	    }

	},
	custom_apply_discount: function(frm,cdt,cdn) {
	    if (frm.doc.custom_discount<-100 || frm.doc.custom_discount>30) {
            frappe.msgprint(__('Can Apply discount between -100 to 30'));
            frappe.validated = false;
            return
        }
		frappe.call({
        type: "POST",
        method: "btb_cvs_support.api.btb_quotation.applyDiscount",
        args: {
            "quote_name": cdn,
            "discount": frm.doc.custom_discount
        },
        callback: function (result) {
             assignQuoteLineItem(frm, cdn);
             loadOneCPQTab(frm);
             assignOneCPQQuoteTotal(frm,cdn);
        }
    });
	},
	custom_download_items: function(frm,cdt,cdn) {
	    console.log('frm.doc : ',frm.doc);
	    var data = [];
				var docfields = [];
				data.push([__("Bulk Edit {0}", ['Items'])]);
				data.push([]);
				data.push([]);
				data.push([]);
				data.push([__("The CSV format is case sensitive")]);
				data.push([__("Do not edit headers which are preset in the template")]);
				data.push(["------"]);
				$.each(frappe.get_meta('Quotation Item').fields, (i, df) => {
					// don't include the read-only field in the template
					if (frappe.model.is_value_type(df.fieldtype)) {
						data[1].push(df.label);
						data[2].push(df.fieldname);
						let description = (df.description || "") + " ";
						if (df.fieldtype === "Date") {
							description += frappe.boot.sysdefaults.date_format;
						}
						data[3].push(description);
						docfields.push(df);
					}
				});
				// add data
				$.each(frm.doc['items'] || [], (i, d) => {
					var row = [];
					$.each(data[2], (i, fieldname) => {
						var value = d[fieldname];
						// format date
						if (docfields[i].fieldtype === "Date" && value) {
							value = frappe.datetime.str_to_user(value);
						}
						row.push(value || "");
					});
					data.push(row);
				});
				frappe.tools.downloadify(data, null, 'Items');
				return false;
	},
	 setup(frm) {
    // Patch only once per browser tab
    if (window.__quotation_copy_patch_applied) return;
    window.__quotation_copy_patch_applied = true;

    const original_copy_doc = frappe.model.copy_doc;

    frappe.model.copy_doc = function (...args) {
      // Keep signature compatibility across Frappe versions
      // copy_doc(doc, from_amend?)
      const doc = args[0];
      const from_amend = args[1];

      const newdoc = original_copy_doc.apply(this, args);

      // Only touch Quotation duplicates (skip amendments)
      if (
        doc && newdoc &&
        doc.doctype === 'Quotation' &&
        newdoc.doctype === 'Quotation' &&
        from_amend !== 1
      ) {
        try {
          // Optional: mark so we can show a toast on the new form
          newdoc.__from_custom_duplicate = 1;
          if(newdoc.custom_customizable == 1)frappe.model.set_value(newdoc.doctype, newdoc.name, "custom_created_from", frm.doc.name);

        } catch (e) {
          console.error('Quotation duplicate patch error:', e);
        }
      }

      return newdoc;
    };
  }
})
