function assignQuoteLineItem(frm, cdn) {
    console.log('qli assign cal start :',new Date())
     cols=[];
    visCols = frm.get_field('items').grid.visible_columns;
    for(i=0;i<visCols.length;i++){
        colData = visCols[i][0];
        data = [];
        col={label:colData.label,fieldtype:colData.fieldtype,fieldname:colData.fieldname,bold:colData.bold,reqd:colData.reqd};
        data.push(col);
        data.push(visCols[i][1])
        cols.push(data)
    }
    frappe.call({
        type: "GET",
        method: "btb_cvs_support.api.onecpq_quote_item.get_quotation_items",
        args: {
            "quote_name": cdn,
            "currency": frm.doc.currency,
            "visibleFields": JSON.stringify(cols)
        },
